"""
Invoice export to the billing API (written against pydantic 1.10).

Provides:
  - export_invoice(data: dict) -> str
"""
from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, ValidationError, validator
from pydantic.json import ENCODERS_BY_TYPE


def _to_utc_datetime(value: datetime) -> datetime:
    """Convert naive datetimes to UTC; convert aware datetimes to UTC."""
    if value.tzinfo is None or value.tzinfo.utcoffset(value) is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def _format_issued_at_utc_z(dt: datetime) -> str:
    """YYYY-MM-DDTHH:MM:SSZ in UTC (second precision)."""
    dt_utc = _to_utc_datetime(dt)
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")


def _quantize_2dp(d: Decimal) -> Decimal:
    # Convert to exactly 2 decimal places (billing API expects that exact form)
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_min_1(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_non_negative(cls, v: Any) -> Any:
        # Let pydantic parse into Decimal; then validate constraints in a second validator.
        return v

    @validator("unit_price")
    def unit_price_constraints(cls, v: Decimal) -> Decimal:
        if v < 0:
            raise ValueError("unit_price must be >= 0")
        # Ensure it is representable with at most 2 decimal places; then quantize.
        quantized = _quantize_2dp(v)
        if v != quantized:
            # Reject inputs with more than 2 decimals to avoid silently rounding.
            raise ValueError("unit_price must have at most 2 decimal places")
        return quantized


class InvoiceExportModel(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    class Config:
        # We'll custom-encode issued_at with required format for the billing API.
        json_encoders = {
            datetime: _format_issued_at_utc_z,
            Decimal: lambda d: f"{_quantize_2dp(d):.2f}",
        }

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v: Any) -> Any:
        # pydantic parses ISO strings already; we only need to ensure timezone handling later.
        return v

    @validator("issued_at")
    def issued_at_to_utc(cls, v: datetime) -> datetime:
        return _to_utc_datetime(v)

    def export_dict(self) -> dict:
        total = sum((line.quantity * line.unit_price for line in self.lines), Decimal("0"))
        total_q = _quantize_2dp(total)

        return {
            "number": self.number,
            "issued_at": _format_issued_at_utc_z(self.issued_at),
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    # Exactly two decimals as a string
                    "unit_price": f"{_quantize_2dp(line.unit_price):.2f}",
                }
                for line in self.lines
            ],
            # Total is required as a string with exactly two decimals
            "total": f"{total_q:.2f}",
        }


def export_invoice(data: dict) -> str:
    """
    Validate invoice input and return billing-API JSON text.

    Expected input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values treated as UTC)
      - lines: list of dicts with
          - sku (str)
          - quantity (int >= 1)
          - unit_price (Decimal >= 0; provided as str/int/float)

    Output JSON:
      - number
      - issued_at: "YYYY-MM-DDTHH:MM:SSZ"
      - lines: [{"sku", "quantity", "unit_price"}] where unit_price is a string with exactly 2 decimals
      - total: string with exactly 2 decimals (sum(quantity * unit_price))

    Raises ValueError for invalid input.
    """
    try:
        model = InvoiceExportModel.parse_obj(data)
    except ValidationError as e:
        # Callers rely on ValueError semantics for invalid inputs.
        raise ValueError(str(e)) from e

    # Produce JSON with the exact required shapes/encodings.
    # Use BaseModel's JSON utilities for consistent formatting.
    # But we must ensure unit_price/total formatting is exact strings with 2 decimals.
    payload = model.export_dict()
    return BaseModel.parse_obj(payload).json()  # not suitable for exact structure typing

from __future__ import annotations

import json
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, Field, model_validator


def _to_utc_second_precision(dt: datetime) -> datetime:
    """
    Convert dt to UTC. If naive, treat as UTC.
    Return with exact second precision (drop sub-second).
    """
    if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
        dt = dt.replace(tzinfo=timezone.utc)
    else:
        dt = dt.astimezone(timezone.utc)

    return dt.replace(microsecond=0)


def _format_issued_at_z(dt: datetime) -> str:
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def _decimal_to_2dp_string(d: Decimal) -> str:
    # Ensure exactly two decimal places in output.
    d = d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return format(d, "f")  # no scientific notation


class InvoiceLine(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal

    @model_validator(mode="before")
    @classmethod
    def _coerce_unit_price(cls, data: Any) -> Any:
        if not isinstance(data, dict):
            return data
        if "unit_price" in data:
            v = data["unit_price"]
            # Convert float via str to reduce binary artifacts.
            if isinstance(v, float):
                v = str(v)
            if isinstance(v, (str, int, Decimal)):
                data["unit_price"] = v
        return data

    @model_validator(mode="after")
    def _validate_unit_price(self) -> "InvoiceLine":
        if self.unit_price < 0:
            raise ValueError("unit_price must be >= 0")
        # Normalize to exactly 2 decimal places for deterministic totals/export.
        self.unit_price = self.unit_price.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return self


class InvoiceExport(BaseModel):
    number: str
    issued_at: str
    lines: List[InvoiceLine]
    total: str

    @model_validator(mode="before")
    @classmethod
    def _validate_and_normalize(cls, data: Any) -> Any:
        if not isinstance(data, dict):
            raise ValueError("invoice payload must be an object")

        # Let pydantic validate number/lines, but we need to normalize issued_at and total.
        out = dict(data)

        # Normalize issued_at -> Z formatted string.
        if "issued_at" not in out:
            raise ValueError("issued_at is required")

        issued_at_val = out["issued_at"]
        if isinstance(issued_at_val, datetime):
            dt = _to_utc_second_precision(issued_at_val)
            out["issued_at"] = _format_issued_at_z(dt)
        elif isinstance(issued_at_val, str):
            # pydantic can parse ISO 8601; implement with fromisoformat for control.
            # Handle trailing 'Z' by converting to +00:00.
            s = issued_at_val.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.fromisoformat(s)
            except ValueError as e:
                raise ValueError("invalid issued_at") from e
            dt = _to_utc_second_precision(dt)
            out["issued_at"] = _format_issued_at_z(dt)
        else:
            raise ValueError("issued_at must be an ISO 8601 string or datetime")

        return out

    @model_validator(mode="after")
    def _compute_total(self) -> "InvoiceExport":
        total = sum((line.quantity * line.unit_price for line in self.lines), Decimal("0"))
        self.total = _decimal_to_2dp_string(total)
        return self

    class Config:
        # Ensure Decimal values are not serialized by pydantic directly (we output strings explicitly for total).
        # (unit_price remains a Decimal in InvoiceLine; we will convert on export.)
        arbitrary_types_allowed = True


def export_invoice(data: dict) -> str:
    """
    Validate an invoice payload and return billing-API JSON text.

    Output fields:
      - number: str
      - issued_at: "YYYY-MM-DDTHH:MM:SSZ" in UTC
      - lines: [{ "sku", "quantity", "unit_price" (string with exactly two decimals) }]
      - total: sum(quantity * unit_price) as string with exactly two decimals
    """
    if not isinstance(data, dict):
        raise ValueError("invoice input must be a dict")

    try:
        inv = InvoiceExport.model_validate(data)
    except Exception as e:
        # Callers expect ValueError on invalid input.
        # Pydantic raises ValidationError which is a ValueError subtype; normalize anyway.
        raise ValueError(str(e)) from e

    # Build final JSON with unit_price formatted to exactly two decimals.
    payload = {
        "number": inv.number,
        "issued_at": inv.issued_at,
        "lines": [
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": _decimal_to_2dp_string(line.unit_price),
            }
            for line in inv.lines
        ],
        "total": inv.total,
    }

    # Ensure deterministic, compact JSON output.
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))

from __future__ import annotations

from typing import Any, Dict, List

from pydantic import ValidationError

from profile_models import Profile


def import_profiles(rows: List[Any]) -> List[Dict[str, Any]]:
    """Validate imported profile rows and return the valid ones as dicts.

    Invalid rows are silently skipped.

    Returned dicts contain exactly:
      {"user_id": int, "display_name": str, "bio": str | None, "zip_code": str}
    """
    out: List[Dict[str, Any]] = []
    for row in rows:
        try:
            profile = Profile.model_validate(row)
        except (ValidationError, ValueError):
            continue

        out.append(
            {
                "user_id": profile.user_id,
                "display_name": profile.display_name,
                "bio": profile.bio,
                "zip_code": profile.zip_code,
            }
        )
    return out
